#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_calculate_wt_with_ct_zero(void) {
    // Setup: Build a process queue where CT is zero for the first node.
    // This will trigger the path: ptr->CT == 0 -> calculate_ct(root);
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;

    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Ensure CT is zero (as per insert function, CT is initialized to 0).
    TEST_ASSERT_EQUAL_INT(0, root->CT);

    // Test: call calculate_wt. It should call calculate_ct internally.
    float avg_wt = calculate_wt(&root);
    // After calculate_ct, CT, TAT should be populated.
    // WT for each process = TAT - BT.
    // We can compute expected average waiting time.
    // For simplicity, we will assert the average is a positive number (since we don't know exact scheduling algorithm).
    TEST_ASSERT_TRUE(avg_wt > 0.0f);

    // Verify that WT fields have been updated.
    node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(ptr->TAT - ptr->BT, ptr->WT);
        ptr = ptr->next;
    }

    // Cleanup
    helper_cleanup_process_queue(&root);
}

